  ('Japonların çiçekleri belirli kurallara göre düzenleme sanatına ne ad verilir?', 'What is the Japanese art of arranging flowers according to set principles called?', '["Ikebana","Bonsai","Origami","Kintsugi"]'::jsonb),
  ('Nobel ödülleri her yıl, Alfred Nobel''in ölüm yıl dönümü olan hangi tarihte verilir?', 'On which date, the anniversary of Alfred Nobel''s death, are the Nobel Prizes awarded each year?', '["December 10","January 1","June 21","October 24"]'::jsonb),
  ('Ülkelerin satın alma gücünü bir hamburger fiyatıyla karşılaştıran ''Big Mac Endeksi''ni hangi yayın yayımlar?', 'Which publication produces the ''Big Mac Index'', comparing countries'' purchasing power through the price of a burger?', '["The Economist","The Financial Times","Forbes","Bloomberg"]'::jsonb),
  ('Cadılar Bayramı''nda (Halloween) oyulup içine mum konan sebze hangisidir?', 'Which vegetable is carved and lit with a candle inside at Halloween?', '["A pumpkin","A watermelon","A cabbage","An aubergine"]'::jsonb),
  ('Dünya Ekonomik Forumu''nun yıllık toplantısı hangi İsviçre kasabasında yapılır?', 'The World Economic Forum''s annual meeting is held in which Swiss town?', '["Davos","Zermatt","Lugano","Gstaad"]'::jsonb)
  ) v(soru, en_soru, en_secenekler)
  join public.questions q on q.soru = v.soru and q.created_at >= transaction_timestamp()
on conflict (question_id, dil) do nothing;

-- ---------------------------------------------------- Çevrilmeyenler
insert into public.ceviri_atlanan (question_id, dil, neden, kod)
select q.id, 'en', v.neden, 'cevrilemez'
  from (values
  ('Aziz Nesin''in, fırsatçı bir köylünün politikacılığa yükselişini anlatan romanı hangisidir?', 'Aziz Nesin''in Türkçe adlı romanları İngilizce oyuncuya yabancı; çeviri adlar yerleşik olmadığı için soru anlamsızlaşıyor.'),
  ('2009''da tedavüle giren 10 Türk lirası banknotunun arka yüzünde portresi bulunan matematikçi kimdir?', 'Türk banknotunun tasarımına dayanıyor; İngilizce oyuncu için bağlamı olmayan yerel bir ayrıntı.'),
  ('1961''de yayımlanan ''Tuhaf Bir Kadın'' romanının yazarı kimdir?', 'Türk edebiyatına özgü, İngilizceye çevrilmiş tanınmış bir karşılığı olmayan eser; İngilizce oyuncu için anlamlı değil.'),
  ('Lütfi Ömer Akad''ın ''Gelin'' ve ''Düğün'' ile başlayan göç üçlemesi hangi filmle tamamlanır?', 'Yeşilçam yönetmeni Lütfi Akad''ın Türkçe adlı filmlerini soruyor; filmler uluslararası adlarla tanınmadığı için İngilizce oyuncu için anlamlı değil.')
  ) v(soru, neden)
  join public.questions q on q.soru = v.soru and q.created_at >= transaction_timestamp()
on conflict (question_id, dil) do nothing;

-- ---------------------------------------------------- Karıştırma (TR + EN aynı permütasyon)
drop table if exists pg_temp._parti_karistir;
create temp table _parti_karistir as
select q.id, array_agg(s.idx order by s.rnd) as perm
  from public.questions q
  cross join lateral (
    select (ordinality - 1)::int as idx, random() as rnd
      from jsonb_array_elements(q.secenekler) with ordinality
  ) s
 where q.created_at >= transaction_timestamp()
 group by q.id;

update public.questions q
   set secenekler = (select jsonb_agg(q.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o)),
       dogru_cevap = (array_position(k.perm, q.dogru_cevap::int) - 1)::smallint
  from _parti_karistir k
 where q.id = k.id;

update public.question_translations t
   set secenekler = (select jsonb_agg(t.secenekler -> u.p order by u.o)
                       from unnest(k.perm) with ordinality u(p, o))
  from _parti_karistir k
 where t.question_id = k.id;

drop table if exists pg_temp._parti_karistir;
